var rows = $input.all();
var sent = 0, replied = 0, interviews = 0;
var topScore = -1, topCompany = '', topTitle = '';
for (var i = 0; i < rows.length; i++) {
  var r = rows[i].json || {};
  if (!r || Object.keys(r).length === 0) continue;
  var st = String(r.status || '').toLowerCase();
  var fb = String(r.feedback_status || '').toLowerCase();
  var wasSent = (st === 'sent' || st === 'replied' || st === 'auto_reply' || st === 'interview_invite' || st === 'bounced' || r.applied === true);
  if (wasSent) sent++;
  if (fb === 'replied' || st === 'replied') replied++;
  if (fb === 'interview_invite' || st === 'interview_invite') { replied++; interviews++; }
  var fs = (r.fit_score !== null && r.fit_score !== undefined && !isNaN(Number(r.fit_score))) ? Number(r.fit_score) : -1;
  if (fs > topScore) { topScore = fs; topCompany = r.company || ''; topTitle = r.job_title || 'Industrial Engineer'; }
}
var rate = sent > 0 ? Math.round((replied / sent) * 100) : 0;
var topLine = (topScore >= 0) ? ('Top Match: ' + topTitle + ' @ ' + topCompany + ' (' + topScore + '%)') : 'Top Match: N/A (fit scoring not yet enabled)';
var style = 'Best Cover Letter Style: N/A (style tagging not yet enabled)';
var LF = String.fromCharCode(10);
var text = '\ud83d\udcca Weekly Job Search Report' + LF +
  'Applied: ' + sent + ' | Replies: ' + replied + ' | Response Rate: ' + rate + '%' + LF +
  'Interviews: ' + interviews + LF +
  topLine + LF +
  style;
return [{ json: { sent: sent, replied: replied, interviews: interviews, response_rate: rate, report_text: text } }];
